      // itself outlive a short window; pinned to 5 s so the settle plus
      // the probe below stay inside the 12 s fresh window even when every
      // bound is hit.
      await harness.waitForOutput(
        settleMs: 200,
        timeout: const Duration(seconds: 5),
      );
