      // run late (timers never fire early), which is the safe direction.
      const testWindow = Duration(seconds: 12);
      final harness = await FaCliHarness.spawn(
        extraEnv: {
          'HOME': tempHome.path,
          kSigintWindowEnvVar: '${testWindow.inMilliseconds}',
